24	const BASE_PRICE_BY_TYPE: Record<string, number> = {
25	  sword: 100,
26	  amulet: 60,
27	  staff: 80,
28	  potion: 40,
29	  rune: 25,
30	  moonstone: 25,
31	};
32	
33	const FIRST_INSURANCE_MULTIPLIER = 1.1;
34	const CONTRACT_FEE = 5;
35	
36	const BUILDING_BLOCK_SIZE = 3;
37	const BUILDING_BLOCK_BASE_PRICE = 60;
38	
39	const CURSED_SURCHARGE_RATE = 0.5;
40	const HIGH_ENCHANTMENT_LEVEL = 5;
41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
42	
43	// Each surcharge adds a percentage of the base price when its condition holds.
44	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
45	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
46	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
47	  {
48	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
49	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
50	  },
51	];
52	
53	const totalSurchargeRateFor = (item: Item): number =>
54	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
55	    (total, surcharge) => total + surcharge.rate,
56	    0,
57	  );
58	
59	// Risk surcharges apply per item, before the contract-level multiplier and fee.
60	const riskAdjustedPriceOfItem = (item: Item): number =>
61	  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));
62	
63	const sumOfIndividualPrices = (items: Item[]): number =>
64	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
65	
66	// "Alike" in the price list means same type — material and enchantment do not
67	// affect whether components group into a building block.
68	const groupByType = (items: Item[]): Item[][] => {
69	  const groups = new Map<string, Item[]>();
70	
71	  for (const item of items) {
72	    const group = groups.get(item.type) ?? [];
73	    group.push(item);
74	    groups.set(item.type, group);
75	  }
76	
77	  return [...groups.values()];
78	};
79	
80	// Every three alike components form a building block priced at 60 G; the
81	// remainder of the group is priced individually.
82	const priceOfAlikeGroup = (group: Item[]): number => {
83	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
84	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
85	
86	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
87	};
88	
89	// The insured value of the whole list: price-list figures plus per-item risk
90	// surcharges, before any contract-level multiplier or fee.
91	const insuredValueOf = (items: Item[]): number =>
92	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
93	
94	const LOYALTY_YEARS = 2;
95	const LOYALTY_DISCOUNT_RATE = 0.2;
96	
97	const loyaltyMultiplierFor = (customer: Customer): number =>
98	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
99	
100	// Customer-dependent factors that scale the whole contract, as opposed to the
101	// per-item risk surcharges already folded into the insured value.
102	const contractMultiplierFor = (customer: Customer): number =>
103	  loyaltyMultiplierFor(customer) * FIRST_INSURANCE_MULTIPLIER;
104	
105	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
106	// no test yet lands on a half-way value, so the rounding *direction* stays
107	// unspecified until the "rounds in MHPCO's favor" test pins it.
108	const quoteStep = (step: Step, customer: Customer): StepResult => ({
109	  premium:
110	    Math.round(insuredValueOf(step.items!) * contractMultiplierFor(customer)) +
111	    CONTRACT_FEE,
112	});
113	
114	export const runScenario = (scenario: Scenario): ScenarioResult => ({
115	  results: scenario.steps.map((step) => quoteStep(step, scenario.customer)),
116	});
